Consider the discrete state space $\mathcal{S} = \mathcal{V}^d$ with vocabulary $\mathcal{V} = \{1, \ldots, M\}$. 
Let $P$ be the true data distribution and let $\widehat{P}$ be the distribution generated by a DFM model using factorized velocity estimators $\widehat{u}_\theta^1, \ldots, \widehat{u}_\theta^d$.
For each coordinate $i_0 \in [d]$, define the factorized risk as the mean squared error of its velocity estimator:
\begin{align*}
    \mathcal{R}^{i_0}(\widehat{\Theta}) 
    := \int_{t_0}^T \underset{X_t\sim p_t(x)}
    {{\mathbb{E}}}\|u^{i_0}(X_t,t) - \widehat{u}^{i_0}_\theta(X_t,t)\|_2^2 \dd t,
\end{align*}
where the time interval is clipped to $[t_0, T]$ to ensure numerical stability and $p_t(x)$ is true probability path generated by factorized velocities $u^1, \ldots, u^d$. Then, the total variation distance between the true and generated distributions is bounded by the sum of the risks from each factorized component:
\begin{align*}
    {\rm TV}(P,\widehat{P})
    \lesssim 
    \sqrt{M} \exp(M_u) 
    \sum_{i_0 \in [d]} \sqrt{\mathcal{R}^{i_0}(\widehat{\Theta})},
\end{align*}
where $M_u$ is the upper bound of estimated velocity such that $\abs{u_t^{\theta,i_0}(y,x)} \leq M_u$ for all $y,x \in \mathcal{S}$.

Let $a,b\in\mathbb{R}$ satisfy $a<b$.
Let $y(t)$ and $f(t)$ be two real value function defined on $[a,b]$.
Suppose that $y(t)$ is differentiable on $[a,b]$ and satisfies:
\begin{align*}
    \frac{\dd }{\dd t}y(t)\leq y(t)f(t), t\in[a,b].
\end{align*}
Then we have:
\begin{align*}
    y(b)\leq y(a)\exp(\int_a^b f(s) \dd s).
\end{align*}

Let the true probability vector $p_t$ and the estimated vector $p_{t,\theta}$ be solutions to the linear differential systems
\begin{align}

    \begin{cases}
    \frac{\dd}{\dd t}p_t= U_tp_t, \\
    \frac{\dd}{\dd t}p_{t,\theta}= U_{t,\theta}p_{t,\theta},
    \end{cases}
\end{align}
with a shared initial condition $p_0 = p_{0,\theta}$. 
Let the evolution operator for the estimated system be $\mathcal{P}_{s,t,\theta}\in\mathbb{R}^{|S|\times|S|}$, which is the solution to $\frac{\dd}{\dd t}\mathcal{P}_{s,t,\theta} = U_{t,\theta}\mathcal{P}_{s,t,\theta}$ with $\mathcal{P}_{s,s,\theta}=I$. 
The difference between the distributions at time $t>0$ is given by
\begin{align*}
    p_{t,\theta} - p_t
    = \int_0^t \mathcal{P}_{s,t,\theta}(U_{s,\theta}-U_s)p_s \dd s.
\end{align*}

Let $\mathcal{T}^{h,s,r}_R(C_\mathcal{T},C^{2,\infty}_{KQ},C_{KQ},C^{2,\infty}_{OV},C_{OV},C_{E},C^{2,\infty}_{F},C_{F},L_\mathcal{T})$ represent the class of transformer network with parameter bound.
Then for data points $x$ such that $\|x\|_2\leq B_X$, we have:
\begin{align*}
    & ~ \log\mathcal{N}(\mathcal{T}^{h,s,r}_R,\epsilon,n,\|\cdot\|_2) \\
    \leq & ~
    \frac{\log(nL_\mathcal{T})}{\epsilon^2}\alpha^2(d_0^\frac{2}{3}(C_F^{2,\infty})^\frac{2}{3}+d_0^\frac{2}{3}(2(C_F)^2C_{OV}C_{KQ}^{2,\infty})^\frac{2}{3}+2((C_F)^2C_{OV}^{2,\infty})^\frac{2}{3})^3,
\end{align*}
where $\alpha=(C_F)^2C_{OV}(1+4C_{KQ})(B_X+C_E)$.

Let $\epsilon_c>0$. 
Consider the transformer class $\mathcal{T}^{h,s,r}_R(C_\mathcal{T},C^{2,\infty}_{KQ},C_{KQ},C^{2,\infty}_{OV},C_{OV},C_{E},C^{2,\infty}_{F},C_{F})$ with parameter bound given in E.1 and $x_i$ satisfying $x_i\in \mathcal{S}$.
Then the $\epsilon_c$-covering number of $\mathcal{T}^{h,s,r}_R$ has the following upper bound:
\begin{align*}
    \log\mathcal{N}(\mathcal{T}^{h,s,r}_R,\epsilon_c,n,\|\cdot\|_2)\lesssim
    \frac{\log(nM)}{\epsilon_c^2}M^{24d_0+28}\epsilon^{-16d_0-12}.
\end{align*}

Let $\epsilon_c>0$ and $i_0\in[M]$.
Suppose that for every given $x\in \mathcal{S}$, $u^{i_0}(x,t)$ represent the velocity field of $x$ at time $t$ that follows mixture path setting (E.2).
We define the factorized loss function class by 
\begin{align*}
F^{i_0}_{\rm loss}:=\{\ell^{i_0}(x;u^{i_0}_\theta)|u^{i_0}_\theta\in\mathcal{T}^{h,s,r}_R\},
\end{align*}
where $\mathcal{T}^{h,s,r}_R$ is the transformer class with parameter bound given in 4.1.

Then we have:
\begin{align*}
    \log\mathcal{N}(F^{i_0}_{\rm loss},\epsilon_c,\{x_i\}_{x_i\in \mathcal{S}},|\cdot|)\lesssim \frac{\log(M)-\log(\epsilon_c)}{\epsilon_c^2}M^{24d_0+28}\epsilon^{-16d_0-12}.
\end{align*}

Let $\widehat{u}^{i_0}_\theta$ with parameter $\widehat{\Theta}^{i_0}$ be the velocity estimator trained by minimizing $\widehat{\mathcal{L}}^{i_0}_{\rm CDFM}$ with i.i.d training samples $\{x_i\}_{i=1}^n$, where $x_i\in \mathcal{S}$.
For simplicity, we use $\mathcal{N}$ to denote $\mathcal{N}(F^{i_0}_{\rm loss},\epsilon_c,\{x_i\}_{x_i\in \mathcal{S}},|\cdot|)$.
Then we bound (I), the generalization bound as:
\begin{align*}
    \underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\mathcal{R}^{i_0}(\widehat{\Theta}^{i_0}) -\widehat{\mathcal{R}}^{i_0}(\widehat{\Theta}^{i_0})] 
    \lesssim 
    \underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\widehat{\mathcal{R}}^{i_0}(\widehat{\Theta}^{i_0})] + O(\frac{\kappa}{n} 
    \log \mathcal{N} + \epsilon_c),
\end{align*}
where $\kappa$ denote the upper bound of $\ell^{i_0}(x;u^{i_0}_\theta)$.

Consider the transformer class $\mathcal{T}^{h,s,r}_R$ with parameter bound given in E.1.
Let $\widehat{u}^{i_0}_\theta\in\mathcal{T}^{h,s,r}_R$ with parameter $\widehat{\Theta}^{i_0}$ be the factorized velocity estimator under mixture path setting trained by minimizing $\widehat{\mathcal{L}}^{i_0}_{\rm CDFM}$ with i.i.d training samples $\{x_i\}_{i=1}^n$, where $x_i\in \mathcal{S}$.
Let factorized empirical risk $\widehat{\mathcal{R}}^{i_0}(\widehat{\Theta}^{i_0})$ be as defined in (F.2).
Then we have:
\begin{align*}
    \underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\widehat{\mathcal{R}}^{i_0}(\widehat{\Theta}^{i_0})]\lesssim   \epsilon^\frac{4}{M+2}M^{\frac{12Md_0+25M}{M+2}}.
\end{align*}

Define $\eta(x):[0,\infty)\to [0,1]$ by
\begin{align*}
\eta(x)=
\begin{cases}
    e\cdot\exp(-\frac{1}{1-x}),~ & x\in[0,1), \\
    0,                  ~ & x\in[1,\infty).
\end{cases}
\end{align*}
Then $\eta(t)\in C^\infty$ and $|\frac{\dd^n\eta}{\dd x^n}(x)|\leq e\cdot(\frac{2n}{e})^{2n}$ for all $x\in[0,1]$.

For any coordinate $i_0\in[d]$, let $\widehat{u}^{i_0}_\theta$  be the $i$-th velocity estimator trained by minimizing empirical loss $\widehat{\mathcal{L}}^{i_0}_{\rm CDFM}$ following (2.10).
Let $P$ denote the true distribution and $\widehat{P}$ the distribution generated by the discrete flow matching framework with factorized velocity estimators $\widehat{u}^{1}_\theta, \widehat{u}^{2}_\theta, \ldots, \widehat{u}^{d}_\theta$.
Then for a vocabulary size $M$, the expected total variation distance $\text{TV}(P,\widehat{P})$ over training data $\{x_i\}_{i=1}^n$ is bounded by:
\begin{align*}
    \underset{\{x_i\}_{i=1}^n}
    {{\mathbb{E}}}[\text{TV}(P,\widehat{P})]
    \lesssim 
    M^{7d_0} n^{-\frac{ 1}{9Md_0}}(\log n)^{\frac{1}{9Md_0}}.
\end{align*}
Here we set transformer feature dimension $d_0>25$ for simplicity.
